#!/bin/bash
# Compare the new server against other HTTP servers on loopback:
# nginx, Apache httpd, Caddy, lighttpd, h2o, and the legacy SwiftWebServer.
#
#   scripts/bench-compare.sh [duration_seconds] [output.md]
#
# All servers bind 127.0.0.1 on free high ports, run as the current user with
# temporary configs under $TMPDIR, and are killed on exit. No sudo, no system
# config is touched. Every server returns the same 626-byte body
# (Root/Public/index.html). Load is generated by oha.
#
# Caveat until StaticFiles (#0084) lands: the new server answers from memory
# (`sws-bench serve --body-size 626`), while nginx and Apache serve the file
# from disk (page cache).

set -o pipefail
cd "$(dirname "$0")/.."
DUR="${1:-10}"
OUT="${2:-docs/benchmarks/compare-servers.md}"
WORK="$(mktemp -d "${TMPDIR:-/tmp}/sws-compare.XXXXXX")"
BODY=Root/Public/index.html
PIDS=()

cleanup() {
  for p in "${PIDS[@]}"; do kill -TERM "$p" 2>/dev/null; done
  sleep 1
  for p in "${PIDS[@]}"; do kill -KILL "$p" 2>/dev/null; done
  [ -f "$WORK/nginx.pid" ] && kill -TERM "$(cat "$WORK/nginx.pid")" 2>/dev/null
  [ -f "$WORK/httpd.pid" ] && kill -TERM "$(cat "$WORK/httpd.pid")" 2>/dev/null
  sleep 1
  pkill -f "$WORK" 2>/dev/null
  rm -rf "$WORK"
}
trap cleanup EXIT INT TERM

free_port() { python3 -c 'import socket;s=socket.socket();s.bind(("127.0.0.1",0));print(s.getsockname()[1]);s.close()'; }
wait_port() { for _ in $(seq 1 50); do curl -s -o /dev/null "http://127.0.0.1:$1/index.html" && return 0; sleep 0.1; done; echo "server on $1 did not start" >&2; return 1; }

mkdir -p "$WORK/root" "$WORK/logs"
cp "$BODY" "$WORK/root/index.html"

# --- new server (release) ---
swift build -c release -j 2 --product sws-bench > /dev/null 2>&1 || { echo "build failed"; exit 1; }
SWS_BIN="$(swift build -c release --show-bin-path)/sws-bench"
SWS_PORT=$(free_port)
"$SWS_BIN" serve --host 127.0.0.1 --port "$SWS_PORT" --body-size 626 > "$WORK/logs/sws.log" 2>&1 &
PIDS+=($!)

# --- nginx ---
NGINX_PORT=$(free_port)
cat > "$WORK/nginx.conf" <<EOF
worker_processes auto;
pid $WORK/nginx.pid;
error_log $WORK/logs/nginx-error.log warn;
events { worker_connections 4096; }
http {
  access_log off;
  sendfile on;
  tcp_nopush on;
  keepalive_requests 1000000;
  open_file_cache max=1000;
  client_body_temp_path $WORK/nginx-tmp;
  proxy_temp_path $WORK/nginx-tmp;
  fastcgi_temp_path $WORK/nginx-tmp;
  uwsgi_temp_path $WORK/nginx-tmp;
  scgi_temp_path $WORK/nginx-tmp;
  types { text/html html; }
  server { listen 127.0.0.1:$NGINX_PORT; root $WORK/root; }
}
EOF
mkdir -p "$WORK/nginx-tmp"
/opt/homebrew/bin/nginx -p "$WORK" -c "$WORK/nginx.conf" -g 'daemon off;' > "$WORK/logs/nginx.out" 2>&1 &
PIDS+=($!)

# --- Apache httpd (macOS /usr/sbin/httpd, event MPM) ---
HTTPD_PORT=$(free_port)
M=/usr/libexec/apache2
cat > "$WORK/httpd.conf" <<EOF
ServerRoot "$WORK"
Listen 127.0.0.1:$HTTPD_PORT
PidFile "$WORK/httpd.pid"
ErrorLog "$WORK/logs/httpd-error.log"
LoadModule mpm_event_module $M/mod_mpm_event.so
LoadModule authz_core_module $M/mod_authz_core.so
LoadModule mime_module $M/mod_mime.so
LoadModule dir_module $M/mod_dir.so
LoadModule unixd_module $M/mod_unixd.so
ServerName 127.0.0.1
DocumentRoot "$WORK/root"
<Directory "$WORK/root">
  Require all granted
</Directory>
KeepAlive On
MaxKeepAliveRequests 0
KeepAliveTimeout 30
EnableSendfile On
TypesConfig /dev/null
AddType text/html .html
EOF
/usr/sbin/httpd -f "$WORK/httpd.conf" -DFOREGROUND > "$WORK/logs/httpd.out" 2>&1 &
PIDS+=($!)

# --- Caddy (admin endpoint off, no access log) ---
CADDY_PORT=$(free_port)
cat > "$WORK/Caddyfile" <<EOF
{
  admin off
  auto_https off
  persist_config off
}
http://127.0.0.1:$CADDY_PORT {
  bind 127.0.0.1
  root * $WORK/root
  file_server
}
EOF
XDG_DATA_HOME="$WORK/caddy-data" XDG_CONFIG_HOME="$WORK/caddy-config" \
  /opt/homebrew/bin/caddy run --config "$WORK/Caddyfile" --adapter caddyfile > "$WORK/logs/caddy.log" 2>&1 &
PIDS+=($!)

# --- lighttpd ---
LIGHTTPD_PORT=$(free_port)
cat > "$WORK/lighttpd.conf" <<EOF
server.document-root = "$WORK/root"
server.bind = "127.0.0.1"
server.port = $LIGHTTPD_PORT
server.errorlog = "$WORK/logs/lighttpd-error.log"
server.max-keep-alive-requests = 65535
server.max-keep-alive-idle = 30
server.max-fds = 4096
server.max-connections = 2048
mimetype.assign = ( ".html" => "text/html" )
EOF
/opt/homebrew/bin/lighttpd -D -f "$WORK/lighttpd.conf" > "$WORK/logs/lighttpd.out" 2>&1 &
PIDS+=($!)

# --- h2o ---
H2O_PORT=$(free_port)
cat > "$WORK/h2o.conf" <<EOF
num-threads: $(sysctl -n hw.ncpu)
pid-file: $WORK/h2o.pid
error-log: $WORK/logs/h2o-error.log
listen:
  host: 127.0.0.1
  port: $H2O_PORT
hosts:
  default:
    paths:
      /:
        file.dir: $WORK/root
EOF
/opt/homebrew/bin/h2o -c "$WORK/h2o.conf" > "$WORK/logs/h2o.out" 2>&1 &
PIDS+=($!)

# --- legacy SwiftWebServer (closes every connection; close-mode rows only) ---
swift build -c release -j 2 --product SwiftWebServer > /dev/null 2>&1 || { echo "legacy build failed"; exit 1; }
LEGACY_PORT=$(free_port)
mkdir -p "$WORK/legacy/Public"
cp "$BODY" "$WORK/legacy/Public/index.html"
sed -E "s/\"port\": *[0-9]+/\"port\": $LEGACY_PORT/" Root/http-config.json > "$WORK/legacy/http-config.json"
env ROOT_PATH="$WORK/legacy" LISTEN_HOST=127.0.0.1 "$(swift build -c release --show-bin-path)/SwiftWebServer" > "$WORK/logs/legacy.log" 2>&1 &
PIDS+=($!)

ALL_PORTS="$SWS_PORT $NGINX_PORT $HTTPD_PORT $CADDY_PORT $LIGHTTPD_PORT $H2O_PORT $LEGACY_PORT"
for p in $ALL_PORTS; do wait_port "$p" || { tail -5 "$WORK"/logs/*; exit 1; }; done

# Loopback-only check.
for p in $ALL_PORTS; do
  lsof -nP -iTCP:"$p" -sTCP:LISTEN | awk 'NR>1{print $9}' | grep -qv '^127\.0\.0\.1:' && { echo "port $p not loopback-only" >&2; exit 1; }
done

run() { # name port conns mode
  local name=$1 port=$2 c=$3 mode=$4 extra=""
  [ "$mode" = close ] && extra="--disable-keepalive"
  oha --no-tui --output-format json -z "${DUR}s" -c "$c" $extra "http://127.0.0.1:$port/index.html" > "$WORK/r.json" 2>/dev/null
  python3 - "$name" "$mode" "$c" "$WORK/r.json" <<'PY'
import json, sys
name, mode, c, path = sys.argv[1:]
d = json.load(open(path))
s = d["summary"]; p = d["latencyPercentiles"]
codes = d.get("statusCodeDistribution", {})
errs = sum(d.get("errorDistribution", {}).values())
ok = codes.get("200", 0)
print(f"| {name} | {mode} | {c} | {s['requestsPerSec']:,.0f} | {p['p50']*1000:.3f} | {p['p99']*1000:.3f} | {p.get('p99.9', 0)*1000:.3f} | {ok:,} | {errs} |")
PY
  # Closed-connection runs leave thousands of TIME_WAIT sockets on loopback,
  # which exhausts ephemeral ports and skews the next run. Wait for them to drain.
  for _ in $(seq 1 120); do
    [ "$(netstat -an -p tcp | grep -c TIME_WAIT)" -lt 500 ] && break
    sleep 1
  done
  sleep 2
}

LOAD_BEFORE=$(uptime | sed 's/.*load averages*: //')
ROWS=""
for mode in keepalive close; do
  for c in 16 64; do
    [ "$mode" = close ] && [ "$c" = 64 ] && continue
    SERVERS="new-server:$SWS_PORT nginx:$NGINX_PORT apache:$HTTPD_PORT caddy:$CADDY_PORT lighttpd:$LIGHTTPD_PORT h2o:$H2O_PORT"
    [ "$mode" = close ] && SERVERS="$SERVERS legacy:$LEGACY_PORT"
    for s in $SERVERS; do
      set -- ${s/:/ }
      ROWS+="$(run "$1" "$2" "$c" "$mode")"$'\n'
    done
  done
done
LOAD_AFTER=$(uptime | sed 's/.*load averages*: //')

{
  echo "# HTTP server comparison"
  echo
  echo "- Date: $(date '+%Y-%m-%d %H:%M %Z'), commit $(git rev-parse --short HEAD)"
  echo "- Machine: $(sysctl -n machdep.cpu.brand_string), $(sysctl -n hw.ncpu) cores; load average before / after: ${LOAD_BEFORE} / ${LOAD_AFTER}"
  echo "- Versions: $(/opt/homebrew/bin/nginx -v 2>&1 | sed 's/nginx version: //'); $(/usr/sbin/httpd -v | head -1 | sed 's/Server version: //') (event MPM); Caddy $(/opt/homebrew/bin/caddy version | awk '{print $1}'); $(/opt/homebrew/bin/lighttpd -v 2>&1 | head -1 | awk '{print $1}'); h2o $(/opt/homebrew/bin/h2o --version 2>&1 | head -1 | awk '{print $3}'); oha $(oha --version | awk '{print $2}')"
  echo "- Each run: ${DUR}s, 626-byte body, loopback; all servers stay up but are measured one at a time. nginx: worker_processes auto, sendfile, open_file_cache, access log off. Apache: event MPM defaults, unlimited keep-alive requests, sendfile, no access log. Caddy: file_server, admin off, no access log. lighttpd: defaults (single process), keep-alive requests raised. h2o: one thread per core. Legacy SwiftWebServer closes every connection, so it appears in close mode only."
  echo "- Caveat: the new server answers from memory until StaticFiles (#0084); nginx and Apache read the file (page cache)."
  echo
  echo "| Server | Connections | Concurrency | req/s | p50 ms | p99 ms | p99.9 ms | 200s | errors |"
  echo "|---|---|---:|---:|---:|---:|---:|---:|---:|"
  printf "%s" "$ROWS"
} > "$OUT"
cat "$OUT"
